   706|// ─── SCREEN 2: Verify Email + Phone ───────────────────────────────────────
   707|
   708|function MemberVerifyContent({
   709|  userId,
   710|  email,
   711|  phone,
   712|  dialCode,
   713|  onComplete,
   714|  router,
   715|}: {
   716|  userId: string;
   717|  email: string;
   718|  phone: string;
   719|  dialCode: string;
   720|  onComplete: () => void;
   721|  router: ReturnType<typeof useRouter>;
   722|}) {
   723|  const [emailCode, setEmailCode] = useState(['', '', '', '', '', '']);
