   725|  const [emailVerified, setEmailVerified] = useState(false);
   726|  const [phoneVerified, setPhoneVerified] = useState(false);
   727|  const [emailLoading, setEmailLoading] = useState(false);
   728|  const [phoneLoading, setPhoneLoading] = useState(false);
   729|  const [resendTimer, setResendTimer] = useState(0);
   730|  const [activeError, setActiveError] = useState('');
   731|
   732|  const emailRefs = useRef<(TextInput | null)[]>([]);
   733|  const phoneRefs = useRef<(TextInput | null)[]>([]);
   734|  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
   735|
   736|  React.useEffect(() => {
   737|    return () => {
   738|      if (timerRef.current) clearInterval(timerRef.current);
   739|    };
   740|  }, []);
   741|
