   743|    setResendTimer(60);
   744|    if (timerRef.current) clearInterval(timerRef.current);
   745|    timerRef.current = setInterval(() => {
   746|      setResendTimer((prev) => {
   747|        if (prev <= 1) {
   748|          if (timerRef.current) clearInterval(timerRef.current);
   749|          return 0;
   750|        }
   751|        return prev - 1;
