   753|    }, 1000);
   754|  };
   755|
   756|  const handleCodeInput = (
   757|    type: 'email' | 'phone',
   758|    index: number,
   759|    value: string,
   760|  ) => {
   761|    const setCode = type === 'email' ? setEmailCode : setPhoneCode;
   762|    const refs = type === 'email' ? emailRefs : phoneRefs;
   763|    const code = type === 'email' ? [...emailCode] : [...phoneCode];
   764|    const digit = value.replace(/[^0-9]/g, '').slice(-1);
   765|    code[index] = digit;
   766|    setCode(code);
   767|    setActiveError('');
   768|
   769|    if (digit && index < 5) {
   770|      refs.current[index + 1]?.focus();
   771|    }
   772|
   773|    if (code.every((c) => c !== '')) {
   774|      handleVerify(type, code.join(''));
