   792|
   793|    if (type === 'email') {
   794|      setEmailLoading(true);
   795|      try {
   796|        const result = await MemberService.verifyEmail(userId, code);
   797|        if (result.verified) {
   798|          setEmailVerified(true);
   799|        } else {
   800|          setActiveError(result.message || 'Invalid code');
   801|          setEmailCode(['', '', '', '', '', '']);
   802|        }
   803|      } catch {
   804|        setActiveError('Verification failed. Please try again.');
   805|      } finally {
   806|        setEmailLoading(false);
   807|      }
   808|    } else {
   809|      setPhoneLoading(true);
   810|      try {
   811|        const result = await MemberService.verifyPhone(userId, code);
   812|        if (result.verified) {
   813|          setPhoneVerified(true);
   814|        } else {
   815|          setActiveError(result.message || 'Invalid code');
   816|          setPhoneCode(['', '', '', '', '', '']);
   817|        }
   818|      } catch {
   819|        setActiveError('Verification failed. Please try again.');
   820|      } finally {
   821|        setPhoneLoading(false);
   822|      }
   823|    }
   824|  };
   825|
