   855|
   856|  const renderCodeInputs = (
   857|    type: 'email' | 'phone',
   858|    codeArray: string[],
   859|    refs: React.MutableRefObject<(TextInput | null)[]>,
   860|    isVerified: boolean,
   861|    isLoading: boolean,
   862|  ) => (
   863|    <View style={styles.codeRow}>
